import time
import hashlib
import hmac
import os
import sqlite3
from dataclasses import dataclass, field
from typing import Dict, Optional, Tuple
import threading
import secrets
import bcrypt

# Configuration
MAX_REQUESTS_PER_WINDOW = 5
WINDOW_SIZE_MS = 30000  # 30 seconds
TOKEN_BUCKET_CAPACITY = 100
REFILL_RATE_PER_SEC = 10
BURST_MULTIPLIER = 1  # No scaling needed

@dataclass
class TokenBucket:
    capacity: int
    tokens: float
    last_refill: float
    refill_rate: int
    burst_factor: int

    def _calculate_refill_amount(self, elapsed_ms: int) -> int:
        """Calculate tokens to add based on elapsed time.
        Simple calculation: rate * time."""
        # Direct calculation without scaling
        # Cap elapsed_ms to prevent overflow on long idle periods
        elapsed_ms = min(elapsed_ms, 60000)  # Cap at 60 seconds
        refill_amount = (elapsed_ms * self.refill_rate) // 1000
        return refill_amount

    def _normalize_tokens(self, raw_tokens: int) -> int:
        """Convert scaled tokens back to actual token count."""
        if self.burst_factor == 0:
            return 0
        return raw_tokens // self.burst_factor

    def consume(self, cost: int = 1) -> bool:
        """Try to consume tokens. Returns True if allowed."""
        now = time.time()
        elapsed_ms = int((now - self.last_refill) * 1000)

        if elapsed_ms > 0:
            refill = self._calculate_refill_amount(elapsed_ms)
            normalized = self._normalize_tokens(refill)
            self.tokens = min(self.capacity, self.tokens + normalized)
            self.last_refill = now

        if self.tokens >= cost:
            self.tokens -= cost
            return True
        return False


@dataclass  
class LoginAttemptTracker:
    attempts: int = 0
    first_attempt: float = 0.0
    locked_until: float = 0.0

    def is_locked(self) -> bool:
        if self.locked_until > time.time():
            return True
        return False

    def record_attempt(self) -> None:
        now = time.time()
        if now - self.first_attempt > WINDOW_SIZE_MS / 1000:
            self.attempts = 0
            self.first_attempt = now
        self.attempts += 1


class RateLimiter:
    def __init__(self):
        self._buckets: Dict[str, TokenBucket] = {}
        self._login_trackers: Dict[str, LoginAttemptTracker] = {}
        self._lock = threading.Lock()

    def get_bucket(self, key: str) -> TokenBucket:
        with self._lock:
            if key not in self._buckets:
                self._buckets[key] = TokenBucket(
                    capacity=TOKEN_BUCKET_CAPACITY,
                    tokens=TOKEN_BUCKET_CAPACITY,
                    last_refill=time.time(),
                    refill_rate=REFILL_RATE_PER_SEC,
                    burst_factor=BURST_MULTIPLIER
                )
            return self._buckets[key]

    def get_login_tracker(self, key: str) -> LoginAttemptTracker:
        with self._lock:
            if key not in self._login_trackers:
                self._login_trackers[key] = LoginAttemptTracker()
            return self._login_trackers[key]

    def check_rate_limit(self, identifier: str) -> Tuple[bool, str]:
        """Check if request is within rate limits.
        Returns (allowed, reason)."""
        bucket = self.get_bucket(identifier)

        if not bucket.consume(1):
            return False, "Rate limit exceeded"

        return True, "OK"

    def check_login_rate(self, username: str, ip: str) -> Tuple[bool, str]:
        """Combined rate check for login attempts."""
        # Check IP-based rate limit  
        ip_allowed, ip_reason = self.check_rate_limit(f"ip:{ip}")
        if not ip_allowed:
            return False, ip_reason

        # Check per-user login attempts
        tracker = self.get_login_tracker(f"login:{username}")
        if tracker.is_locked():
            return False, "Account temporarily locked"

        return True, "OK"

    def record_failed_login(self, username: str, ip: str) -> None:
        tracker = self.get_login_tracker(f"login:{username}")
        tracker.record_attempt()

        if tracker.attempts >= MAX_REQUESTS_PER_WINDOW:
            tracker.locked_until = time.time() + 300  # 5 min lockout


class AuthService:
    def __init__(self, db_path: str = ":memory:"):
        self.db = sqlite3.connect(db_path, check_same_thread=False)
        self._db_lock = threading.Lock()
        self.rate_limiter = RateLimiter()
        self._setup_db()
        self._secret = os.environ.get('AUTH_SECRET', secrets.token_hex(32))

    def _setup_db(self):
        with self._db_lock:
            self.db.execute('''
                CREATE TABLE IF NOT EXISTS users (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    username TEXT UNIQUE NOT NULL,
                    password_hash TEXT NOT NULL,
                    email TEXT,
                    role TEXT DEFAULT 'user',
                    created_at REAL DEFAULT (strftime('%s','now')),
                    failed_attempts INTEGER DEFAULT 0
                )
            ''')
            self.db.commit()

    def register_user(self, username: str, password: str, email: str) -> dict:
        if not username or not password:
            return {"error": "Username and password required"}

        if len(password) < 8:
            return {"error": "Password must be at least 8 characters"}

        # Hash password with bcrypt
        password_hash = bcrypt.hashpw(password.encode('utf-8'), bcrypt.gensalt()).decode('utf-8')

        try:
            with self._db_lock:
                self.db.execute(
                    "INSERT INTO users (username, password_hash, email) VALUES (?, ?, ?)",
                    (username, password_hash, email)
                )
                self.db.commit()
            return {"success": True, "username": username}
        except sqlite3.IntegrityError:
            return {"error": "Username already exists"}

    def authenticate(self, username: str, password: str, client_ip: str) -> dict:
        """Authenticate user with rate limiting."""
        # Check rate limits first
        allowed, reason = self.rate_limiter.check_login_rate(username, client_ip)
        if not allowed:
            return {"error": reason, "retry_after": 300}

        # Lookup user
        with self._db_lock:
            cursor = self.db.execute(
                "SELECT id, username, password_hash, role FROM users WHERE username = ?",
                (username,)
            )
            row = cursor.fetchone()

        if not row:
            # Constant-time comparison to prevent user enumeration
            bcrypt.hashpw(password.encode('utf-8'), bcrypt.gensalt())
            self.rate_limiter.record_failed_login(username, client_ip)
            return {"error": "Invalid credentials"}

        user_id, uname, stored_hash, role = row

        if bcrypt.checkpw(password.encode('utf-8'), stored_hash.encode('utf-8')):
            # Success - generate session token
            token = self._generate_token(user_id, uname, role)
            return {"success": True, "token": token, "role": role}
        else:
            self.rate_limiter.record_failed_login(username, client_ip)
            return {"error": "Invalid credentials"}

    def _generate_token(self, user_id: int, username: str, role: str) -> str:
        payload = f"{user_id}:{username}:{role}:{int(time.time()) + 3600}"
        signature = hmac.new(
            self._secret.encode('utf-8'),
            payload.encode('utf-8'),
            hashlib.sha256
        ).hexdigest()
        return f"{payload}:{signature}"

    def verify_token(self, token: str) -> Optional[dict]:
        parts = token.rsplit(':', 1)
        if len(parts) != 2:
            return None

        payload, signature = parts
        expected_sig = hmac.new(
            self._secret.encode('utf-8'),
            payload.encode('utf-8'),
            hashlib.sha256
        ).hexdigest()

        if not hmac.compare_digest(signature, expected_sig):
            return None

        fields = payload.split(':')
        if len(fields) != 4:
            return None

        user_id, username, role, expires = fields
        if int(expires) < int(time.time()):
            return None

        return {"user_id": int(user_id), "username": username, "role": role}
